  "nav.docs": "Documentation",
  "docs.title": "Documentation",
  "docs.subtitle": "The complete GameIndex handbook — every screen, feature and shortcut, from your first import to Steam Deck tuning. Search it, jump around, or read it cover to cover.",
  "docs.toc": "Contents",
  "docs.onThisPage": "On this page",
  "docs.quickStart": "Quick Start",
  "docs.quickStartSubtitle": "Essential guides to get up and running with GameIndex in minutes.",
  "docs.relatedTopics": "Related Topics",
  "docs.expandAll": "Expand all",
  "docs.home.title": "The Home Dashboard",
  "docs.home.body": "The **Home** page is GameIndex's dashboard: what you played last, what is downloading and what is worth a look next. It is the default landing page.\n\n## What is on the dashboard\n- **Spotlight hero**: recent games shown large, with a direct route back into your last session.\n- **Quick stats**: library totals and playtime at a glance.\n- **Widgets** in the left column: quick launch, weekly activity, achievements and the friends feed.\n- **Continue playing** and **recently added** rails, so resuming or checking a fresh import takes one click.\n- **Active downloads**, the **wishlist**, **deals** and **news** rails on the right.\n\n## Making it yours\n- Press **Customize** above the dashboard to toggle individual sections on or off.\n- In **Simple UI mode** the dense dashboard is replaced by a short welcome header with **Browse store** and **Your library** buttons.\n- Pick the page that opens on launch in **Settings → Launcher → Landing page**.\n\n> **Tip:** every rail is keyboard- and controller-navigable, so Home is a fine entry point for a couch session too.\n\n## A good daily routine\n- Start on Home and check the continue-playing row; it usually answers the *what next* question immediately.\n- Glance at recently added after an import, so nothing sits unnamed or without artwork.\n- Watch the downloads rail instead of opening the Downloads page for a single transfer.\n- Keep the wishlist short so the deals and wishlist rails stay useful rather than noisy.",
  "docs.globalsearch.title": "Global Search & Quick Find",
  "docs.globalsearch.body": "GameIndex has several search surfaces, and knowing which one to reach for saves the most time.\n\n## From anywhere\n- **`Ctrl+K`** (or **`Cmd+K`**) — or the **search button in the top bar** — opens the command palette: games, pages, settings, actions and a calculator in one field.\n- Type a few letters and press `Enter`; the palette searches your library, the store and your recent commands together.\n\n## Per-page search\n- **`/`** focuses the search field on pages that have one — Store, Storage, Downloads, Documentation and Settings.\n- **Sidebar search** filters the library as you type and keeps working while you scroll.\n- **Settings search** matches tab names, section titles and keywords such as *HDR* or *deadzone*, so you can jump straight to a control.\n- **Documentation search** looks inside every article body, so a single term like *prefix* lands on the full page.\n\n## Getting better results\n- Prefer a distinctive word over a fragment of a sentence; search matches words, not intent.\n- Use the palette to **go** somewhere and page search to **narrow** what is already in front of you.\n- In the Store, search and filters stack, and the resulting combination is shareable as a URL.\n- If a search looks empty, clear the active filters first — a hidden-platform filter can hide good results.\n\n> **Tip:** the palette remembers recent commands, so the second search of the day is usually a two-key affair.",
  "docs.plugins.title": "Plugins & Search Providers",
  "docs.plugins.body": "Plugins extend GameIndex with community-written download-search providers. They are optional `.js` files that you import yourself.\n\n## Installing a plugin\n1. Open **Settings → Plugins**.\n2. Press **Import plugin** and choose a `.js` file on disk.\n3. GameIndex reads and validates the file, then shows a **trust gate**: name, description, source URL, the file's SHA-256 hash and a plain-language warning.\n4. Review the details and confirm — nothing is written or enabled until you do.\n\n## Managing installed plugins\n- Enable or disable a plugin without removing it, so a misbehaving provider can be switched off quickly.\n- Remove plugins you no longer use.\n- The list surfaces the error text a plugin reported the last time it failed.\n- **Bulk import** scans several files at once and reports which ones were skipped, and why.\n\n## Safety and troubleshooting\n- Only import plugins you trust: a plugin contributes code that the app runs, so treat unknown files like any other download.\n- If the publisher lists a SHA-256 hash, compare it with the value shown in the trust gate before installing.\n- A plugin that reports a runtime error can be disabled to restore normal search behaviour.\n- If a provider returns nothing, check that its plugin is enabled and that any API key or endpoint it needs is still valid.\n\n> **Note:** plugins only contribute download search results; the trust gate is your chance to review one before it runs.",
  "docs.launcher.title": "Launcher, Startup & Tray",
  "docs.launcher.body": "**Settings → Launcher** controls how the app starts, how the window behaves and when Windows asks for permission.\n\n## Startup\n- **Landing page**: choose which page opens on launch — Home, Library, Store, Wishlist, Deals, Activity, Achievements, Downloads, Storage, News or Community.\n- **Auto-start on boot**: start GameIndex with your session, so a sync or a download can carry on in the background.\n\n## Window and tray\n- **Close to tray**: the close button hides the window instead of quitting, keeping downloads and playtime tracking alive.\n- **Minimize on launch**: the window steps aside when a game starts.\n- **Restore on exit**: bring GameIndex back to the front when the game closes.\n\n## Elevation prompts (Windows)\n- **Disable elevation prompts** suppresses the UAC dialog for elevated launches.\n- Leave it off unless the repeated prompts genuinely get in the way; per-game **Run as Administrator** keeps working either way.\n\n> **Tip:** close-to-tray plus auto-start is the usual combination for a machine that also acts as an always-on download box.\n\n## Choosing the right behaviour\n- Point the landing page at the page you open first every session; the command palette reaches the rest.\n- Turn off close-to-tray if you would rather quit the app cleanly from the close button.\n- Minimize and restore on exit help with a game that fights for focus on a multi-monitor setup.\n- On a laptop, leaving auto-start off is usually the better trade-off for battery life.",
